(() => {
 const visible=e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden';
 if(context.ui.upload_duplicate_text&&document.body.innerText.includes(context.ui.upload_duplicate_text))throw Object.assign(new Error('Отчёт уже загружен; повтор запрещён'),{code:'REPORT_ALREADY_IMPORTED'});
 const cards=[...document.querySelectorAll(context.ui.report_scope_selector)].filter(visible);
 if(cards.length!==1||!new RegExp('(^|[^0-9])'+context.inn+'([^0-9]|$)').test(cards[0].innerText))throw Object.assign(new Error('Карточка не подтверждает полный ИНН'),{code:'REPORT_IDENTITY_MISMATCH'});
 const key=context.candidate_identity_key;
 if(typeof key!=='string'||!key.trim()||key.length>256||!context.report.file_selection_verified)throw Object.assign(new Error('Не подтверждены файл и ключ карточки'),{code:'REPORT_IDENTITY_MISMATCH'});
 if(!context.capture_key&&key!==context.report.report_key)throw Object.assign(new Error('Открыта другая карточка'),{code:'REPORT_IDENTITY_MISMATCH'});
 return key;
})()

(() => {
 const visible=e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden', roots=[...document.querySelectorAll(context.ui.validation_scope_selector||context.ui.report_scope_selector)].filter(visible);
 if(roots.length!==1)return false;
 const matches=[...roots[0].querySelectorAll(context.ui.validation_status_selector)].filter(e=>visible(e)&&[context.ui.validation_success_text,context.ui.validation_failure_text].includes(e.innerText.trim()));
 if(matches.length!==1)return false;
 const protocols=[...roots[0].querySelectorAll(context.ui.protocol_selector)].filter(visible);
 if(protocols.length!==1||!protocols[0].innerText.trim())return false;
 return {status:matches[0].innerText.trim(),protocol:protocols[0].innerText};
})()

(() => {
 const bad = message => { throw Object.assign(new Error(message),{code:'MISSING_PARAMETER'}); };
 if (!['preflight','validate_only','send'].includes(context.mode)) bad('Некорректный mode');
 if (!/^\d{10}(\d{2})?$/.test(context.inn||'')) bad('Требуется полный ИНН организации');
 if (context.certificate_inn != null && !/^\d{10}(\d{2})?$/.test(context.certificate_inn)) bad('Некорректный certificate_inn');
 const plans=context.authority_prefixes == null ? [{authority:context.authority,prefixes:context.prefixes}] : context.authority_prefixes;
 if (!Array.isArray(plans) || !plans.length || plans.length>3) bad('Требуется от одного до трёх ведомств');
 const seen=new Set();
 return plans.map(plan=>{
  if (!['FNS','SFR','ROSSTAT'].includes(plan.authority) || seen.has(plan.authority)) bad('Неизвестное или повторное ведомство');
  seen.add(plan.authority);
  if (!Array.isArray(plan.prefixes) || !plan.prefixes.length || plan.prefixes.some(p=>typeof p!=='string'||!p.trim())) bad('Не заданы префиксы файлов');
  const ui={...context.ui,...(plan.ui||{})};
  const required=['organization_selector','report_scope_selector','report_key_expression','validation_status_selector','protocol_selector','validation_success_text','validation_failure_text'];
  if(context.mode==='send'&&context.submit_enabled===true)required.push('sent_status_selector');
  const missing=context.mode==='preflight'?[]:required.filter(k=>!ui[k]);
  if(context.mode!=='preflight')for(const k of ['upload_steps','validate_steps',...(context.mode==='send'&&context.submit_enabled===true?['reopen_steps','submit_steps']:[])])if(!Array.isArray(ui[k])||!ui[k].length)missing.push(k);
  if(!ui.authority_paths?.[plan.authority])missing.push('authority_paths');
  if(missing.length)throw Object.assign(new Error('Не настроены UI-привязки: '+missing.join(', ')),{code:'UI_BINDING_REQUIRED'});
  return {...plan,ui};
 });
})()

(() => {
 const selected=new Set(),reports=[];
 for(const plan of context.plans){const current=new Map();for(const prefix of plan.prefixes){
  const files=context.directory_files.filter(f=>f.filename.toLowerCase().endsWith('.xml')&&f.filename.startsWith(prefix)).sort((a,b)=>b.modified_ms-a.modified_ms||a.filename.localeCompare(b.filename));
  if(!files.length)throw Object.assign(new Error('Не найден XML для заданного префикса'),{code:'FILE_NOT_FOUND'});
  current.set(files[0].path,files[0]);
 }
 if(context.allow_multiple===false&&current.size>1)throw Object.assign(new Error('Несколько файлов при allow_multiple=false'),{code:'MULTIPLE_FILES'});
 for(const file of current.values()){
  const key=/^[a-z]:[\\/]/i.test(file.path)?file.path.toLowerCase():file.path;
  if(selected.has(key))throw Object.assign(new Error('Один XML выбран для разных ведомств'),{code:'AUTHORITY_FILE_CONFLICT'});
  selected.add(key);reports.push({...file,authority:plan.authority,state:'selected',validation_result:null,sbis_status:null});
 }}return reports;
})()

(() => {
 const visible=e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden', inn=context.certificate_inn||context.inn;
 const rows=[...document.querySelectorAll(context.ui.certificate_rows_selector)].filter(e=>visible(e)&&!e.closest(context.ui.certificate_unusable_selector||'.controls-SpoilerView,[aria-disabled=true],[disabled]')&&!e.querySelector('[aria-disabled=true],[disabled]'));
 const matches=rows.filter(e=>new RegExp('(^|[^0-9])'+inn+'([^0-9]|$)').test(e.innerText));
 if(matches.length!==1)throw Object.assign(new Error(matches.length?'Несколько пригодных подписей с нужным ИНН':'Нет пригодной подписи с нужным ИНН'),{code:matches.length?'CERTIFICATE_AMBIGUOUS':'CERTIFICATE_NOT_FOUND'});
 matches[0].click();return {certificate_selected:true,certificate_inn:inn,eligible_certificate_count:rows.length};
})()

(() => {
 const visible=e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden';
 const rows=[...document.querySelectorAll('[data-minicard-name]')].filter(e=>visible(e)&&e.getAttribute('data-minicard-name')===context.report.filename);
 const normalize=value=>{let r=String(value||'').replace(/\\/g,'/');if(r.startsWith('file:///')){try{r=decodeURIComponent(r.slice(7));}catch{return null;}}if(/^\/[a-z]:\//i.test(r))r=r.slice(1);return /^[a-z]:\//i.test(r)?r.toLowerCase():r;};
 if(rows.length!==1||!rows[0].getAttribute('data-minicard-path')||normalize(rows[0].getAttribute('data-minicard-path'))!==normalize(context.report.path))throw Object.assign(new Error('Не подтверждён единственный файл по имени и полному пути'),{code:'FILE_SELECTION_MISMATCH'});
 return true;
})()
